async function rollbackRun(){return exclusiveControl(async()=>{if(!run?.shadow)throw Error('Контрольная точка не найдена');if(!run.done)throw Error('Остановите задачу и дождитесь её завершения');const files=await run.shadow.rollback();sessionReads.clear();return files;});}
function configureTelegram(){
  if(!config.telegramEnabled||!validTelegramToken(config.telegramToken)||!validTelegramId(config.telegramUserId)){telegram?.stop();telegram=null;return;}
  if(telegram&&telegram.token===config.telegramToken&&telegram.userId===config.telegramUserId)return;
  telegram?.stop();
  telegram=new TelegramBridge({token:config.telegramToken,userId:config.telegramUserId,handlers:{
    run:startRun,stop:async()=>stopRun(),set:updateConfig,
    secrets:()=>[config.apiKey,config.braveApiKey,config.tavilyApiKey,config.telegramToken],
    status:async()=>{const latest=run?.events.findLast(e=>e.type==='status')?.text;return JSON.stringify({active:!!run&&!run.done,taskId:run?.id||null,progress:latest||null,steps:run?.usage?.steps||0,model:config.model,workspace:config.workspace},null,2)},
    logs:async()=>run?run.events.filter(e=>['status','message','error','tool_start','tool_result','file_change','done'].includes(e.type)).map(e=>`${e.type}${e.name?' '+e.name:''}: ${e.text||(e.args?JSON.stringify(e.args):e.path||'')}`).join('\n')||'Событий пока нет.':'Задачи пока нет.',
    settings:async()=>JSON.stringify(publicConfig(),null,2),
    models:async signal=>{const data=await provider('/models',{signal});return 'Модели:\n'+(data.data||[]).map(x=>x.id).filter(Boolean).join('\n')},
    changes:async()=>{if(!run?.shadow)throw Error('Контрольная точка не найдена');return (await run.shadow.diff({maxLength:Infinity})).diff},
    screen:async()=>{const image=run?.events.findLast(e=>e.type==='screen'&&e.image)?.image;if(!image)throw Error('Снимок рабочего стола пока недоступен');return image},
    rollback:async()=>`Откат выполнен. Файлов: ${(await rollbackRun()).length}`
  }});
  void telegram.start();
}
const server = http.createServer(async (req,res) => {
  try {
    const url = new URL(req.url,`http://localhost:${port}`);
    if (url.pathname === '/mcp') return builtinMcpHandler(req,res);
    if (req.method === 'GET' && url.pathname === '/') { let html=await readFile(path.join(root,'public/index.html'),'utf8'); html=html.replace('__TOKEN__',token); res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','Set-Cookie':`diabolix_sse=${token}; HttpOnly; SameSite=Strict; Path=/api/stream`,'Content-Security-Policy':"default-src 'self'; style-src 'self'; script-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'"}); return res.end(html); }
    if (req.method === 'GET' && ['/app.js','/style.css'].includes(url.pathname)) { const content=await readFile(path.join(root,'public',url.pathname.slice(1))); res.writeHead(200,{'Content-Type':url.pathname.endsWith('.js')?'text/javascript; charset=utf-8':'text/css; charset=utf-8'}); return res.end(content); }
    if (!url.pathname.startsWith('/api/')) return json(res,404,{error:'Не найдено'});
    if(req.method==='GET' && url.pathname==='/api/stream'){
      const cookie=(req.headers.cookie||'').split(';').map(v=>v.trim()).find(v=>v.startsWith('diabolix_sse='));if(cookie!==`diabolix_sse=${token}`)return json(res,403,{error:'Доступ запрещён'});
      const id=url.searchParams.get('id'),active=run?.id===id?run:null,archived=active?null:await taskJournal.read(id);if(!active&&!archived)return json(res,404,{error:'Задача не найдена'});
      res.writeHead(200,{'Content-Type':'text/event-stream; charset=utf-8','Cache-Control':'no-cache, no-transform','Connection':'keep-alive','X-Accel-Buffering':'no'});const after=Math.max(0,Number(req.headers['last-event-id']||url.searchParams.get('after'))||0);const events=active?active.events:archived.events.map(e=>e.type==='finished'?{...e,archived:true}:e);for(const event of events)if(event.id>after)res.write(`id: ${event.id}\ndata: ${JSON.stringify(event)}\n\n`);if(archived&&!archived.done){const last=events.at(-1)?.id||0;for(const event of [{id:last+1,type:'error',text:'Задача была прервана перезапуском. Проверьте изменения и результаты перед продолжением.'},{id:last+2,type:'finished',archived:true}])if(event.id>after)res.write(`id: ${event.id}\ndata: ${JSON.stringify(event)}\n\n`)}if(archived||active.done){res.end();return}active.clients.add(res);const heartbeat=setInterval(()=>res.write(': ping\n\n'),15000);req.on('close',()=>{clearInterval(heartbeat);active.clients.delete(res)});return;
    }
    if (req.headers['x-diabolix-token'] !== token) return json(res,403,{error:'Доступ запрещён'});
    if (req.method === 'GET' && url.pathname === '/api/config') return json(res,200,publicConfig());
    if (req.method === 'POST' && url.pathname === '/api/config') return json(res,200,await updateConfig(await body(req)));
    if (req.method === 'POST' && url.pathname === '/api/models') { const data=await provider('/models'); return json(res,200,{models:(data.data || []).map(x=>x.id).filter(Boolean).sort()}); }
    if (req.method === 'POST' && url.pathname === '/api/run') { const b=await body(req);return json(res,200,await startRun(b.message,b.session||crypto.randomUUID())); }
    if (req.method === 'POST' && url.pathname === '/api/resume') {const b=await body(req);if(run&&!run.done)throw Error('Агент уже выполняет задачу');if(config.profile!=='coding')throw Error('Для продолжения выберите профиль «Разработка».');const previous=await taskJournal.read(b.id);const plan=recoveryPlan(previous,config.workspace);for(const item of plan.changed){const output=await sandboxTool('hash_file',{path:item.path},config.workspace,new AbortController().signal);if(!output.startsWith(item.hash+'\n[код: 0]'))throw Error('Файл изменился после прерывания: '+item.path+'. Проверьте проект вручную.')}const message='Продолжи ранее прерванную задачу. Не повторяй уже выполненные действия без необходимости; сначала изучи текущее состояние проекта.\nИсходная задача:\n'+String(plan.task)+'\nПодтверждённые результаты предыдущих инструментов (могут быть неполными):\n'+JSON.stringify(plan.evidence);return json(res,200,await startRun(message,crypto.randomUUID()));}
    if (req.method === 'GET' && url.pathname === '/api/runs') return json(res,200,{runs:await taskJournal.list()});
    if (req.method === 'GET' && url.pathname === '/api/events') {const id=url.searchParams.get('id'),active=run?.id===id?run:null,archived=active?null:await taskJournal.read(id);if(!active&&!archived)return json(res,404,{error:'Задача не найдена'});return json(res,200,{events:(active?.events||archived.events).slice(Math.max(0,Number(url.searchParams.get('after'))||0)),done:active?active.done:true,...(archived?{status:archived.status,task:archived.task,workspace:archived.workspace}:{})}); }
    if (req.method === 'GET' && url.pathname === '/api/changes') { const active=run;if(!active?.shadow||active.id!==url.searchParams.get('id'))return json(res,404,{error:'Изменения задачи недоступны'});return json(res,200,await active.shadow.diff({maxLength:Infinity})); }
    if(req.method==='POST' && url.pathname==='/api/rollback-session')return json(res,200,{ok:true,files:await rollbackRun()});
    if (req.method === 'POST' && url.pathname === '/api/stop') { stopRun();return json(res,200,{ok:true}); }
    return json(res,404,{error:'Не найдено'});
  } catch(e) { return json(res,e.message==='Агент уже выполняет задачу'?409:400,{error:e.message}); }
});
server.listen(port,'127.0.0.1',()=>{console.log(`DiaboliX запущен: http://localhost:${port}`);configureTelegram();});
